import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Img, interpolate, spring } from '../remotionShim';


export type SlowScrollHighlightProps = Record<string, any>;

const SlowScrollHighlight: React.FC<SlowScrollHighlightProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 8,
  screenshotUrl = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/e4518ed6c2a845b2b5cbcd58c033aa20.png",
  planeWidthPercent = 75,
  perspective = 1200,
  rotateY = 22,
  rotateX = 4,
  scale = 1.05,
  paddingTopPercent = 10,
  scrollStartPercent = 0,
  scrollEndPercent = -18,
  scrollEasingStartFrame = 0,
  highlightColor = "#ffff00",
  highlightTopPercent = 14,
  highlightLeftPercent = 22,
  highlightWidthPercent = 55,
  highlightHeightPercent = 2,
  highlightStartFrame = 90,
  highlightSpeed = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const durationInFrames = durationInSeconds * fps;
  const safeEndFrame = Math.max(scrollEasingStartFrame + 1, durationInFrames);

  // Background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Smooth scroll interpolation
  const currentScrollY = interpolate(
    frame,
    [scrollEasingStartFrame, safeEndFrame],
    [scrollStartPercent, scrollEndPercent],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );

  // Highlight drawing animation
  const highlightProgress = spring({
    frame: (frame - highlightStartFrame) * highlightSpeed,
    fps,
    config: { damping: 14, mass: 0.6 }
  });

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      perspective: `${perspective}px`, 
      alignItems: 'center', 
      justifyContent: 'flex-start',
      paddingTop: `${paddingTopPercent}%`,
      overflow: 'hidden',
    }}>
      <div style={{
        width: `${planeWidthPercent}%`,
        transform: `rotateY(${rotateY}deg) rotateX(${rotateX}deg) scale(${scale})`,
        transformStyle: 'preserve-3d',
        display: 'flex',
        alignItems: 'flex-start',
        justifyContent: 'center',
        position: 'relative',
        transition: 'none',
      }}>
        {/* Scrollable Canvas Container */}
        <div style={{
          width: '100%',
          transform: `translateY(${currentScrollY}%)`,
          position: 'relative',
          boxShadow: '-15px 25px 80px rgba(0, 0, 0, 0.7)',
          borderRadius: '12px',
          backgroundColor: '#ffffff',
          transition: 'none',
        }}>
          {/* Main Screenshot */}
          <Img 
            src={screenshotUrl} 
            style={{ 
              width: '100%', 
              height: 'auto', 
              display: 'block',
              borderRadius: '12px',
              transition: 'none',
            }} 
          />
          
          {/* Title Highlight Overlay */}
          <div style={{
            position: 'absolute',
            top: `${highlightTopPercent}%`,
            left: `${highlightLeftPercent}%`,
            width: `${highlightWidthPercent}%`,
            height: `${highlightHeightPercent}%`,
            backgroundColor: highlightColor,
            mixBlendMode: 'multiply',
            transformOrigin: 'left center',
            transform: `scaleX(${Math.max(0, highlightProgress)})`,
            pointerEvents: 'none',
            borderRadius: '4px',
            transition: 'none',
          }} />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SlowScrollHighlight;